export function findBranchSubagentProfileMarker(branch: readonly unknown[]): { name?: SubagentProfileName; invalid?: string } | undefined {
	let invalid: string | undefined;
	for (let index = branch.length - 1; index >= 0; index -= 1) {
		const entry = branch[index];
		if (!entry || typeof entry !== "object" || Array.isArray(entry)) continue;
		const record = entry as Record<string, unknown>;
		if (record.type !== "custom" || record.customType !== SUBAGENT_PROFILE_ENTRY_TYPE) continue;
		const data = record.data;
		if (!data || typeof data !== "object" || Array.isArray(data)) {
			invalid ??= "malformed profile marker";
			continue;
		}
		const marker = data as Record<string, unknown>;
		if (marker.version !== 1 || !isSupportedSubagentProfileName(marker.name)) {
			invalid ??= "unknown or malformed profile marker";
			continue;
		}
		return { name: marker.name, ...(invalid ? { invalid } : {}) };
	}
	return invalid ? { invalid } : undefined;
}

