function restorePersistedSubagentProfile(warning?: string): SubagentProfileRestore {
	const detected = inferPersistedSubagentProfile();
	if (detected) {
		const { profileName } = applySubagentProfile(detected);
		return {
			name: profileName,
			source: "persisted",
			shouldAppendMarker: true,
			...(warning ? { warning } : {}),
		};
	}
	clearSubagentProfileOverlay();
	return {
		name: "default",
		source: "default",
		shouldAppendMarker: false,
		...(warning ? { warning } : {}),
	};
}

export function restoreSubagentProfileSession(branch: readonly unknown[]): SubagentProfileRestore {
	const marker = findBranchSubagentProfileMarker(branch);
	if (marker?.name) {
		try {
			const { profileName } = applySubagentProfile(marker.name);
			return {
				name: profileName,
				source: "marker",
				shouldAppendMarker: Boolean(marker.invalid),
				...(marker.invalid ? { warning: marker.invalid } : {}),
			};
		} catch {
			const warning = [marker.invalid, `profile marker '${marker.name}' could not be restored`]
				.filter(Boolean)
				.join("; ");
			return restorePersistedSubagentProfile(warning);
		}
	}
	return restorePersistedSubagentProfile(marker?.invalid);
}

